async function main(ctx) {
  const input = ctx.input || {};

  const operationRaw = String(input.operation ?? input.op ?? '').trim().toLowerCase();
  let operation = operationRaw;
  if (operation === 'remove') operation = 'delete';
  if (operation === 'create') operation = 'upload';
  if (operation === 'edit') operation = 'update';

  const allowed = new Set(['list', 'get', 'upload', 'update', 'delete']);
  if (!allowed.has(operation)) {
    throw new Error('operation is required and must be one of: list, get, upload, update, delete');
  }

  const productId = input.productId ?? input.product_id ?? input.productID ?? input.id;
  if (productId === undefined || productId === null || String(productId).trim() === '') {
    throw new Error('productId is required');
  }

  // Disallow base64-style inputs entirely (security + policy)
  if (typeof input.imageBase64 === 'string' && input.imageBase64.trim().length) {
    throw new Error('imageBase64 is not allowed. Use imageUrl or attachmentId.');
  }
  if (typeof input.imageDataUrl === 'string' && input.imageDataUrl.trim().length) {
    throw new Error('imageDataUrl is not allowed. Use imageUrl or attachmentId.');
  }

  const out = {
    operation,
    product_id: String(productId).trim(),
  };

  // image_id required for get/update/delete
  if (operation === 'get' || operation === 'update' || operation === 'delete') {
    const imageId = input.imageId ?? input.image_id;
    if (imageId === undefined || imageId === null || String(imageId).trim() === '') {
      throw new Error('imageId is required when operation is get, update, or delete');
    }
    out.image_id = String(imageId).trim();
  }

  const metadata = (input.metadata && typeof input.metadata === 'object' && !Array.isArray(input.metadata))
    ? { ...input.metadata }
    : null;

  // Build image payload for upload/update
  if (operation === 'upload' || operation === 'update') {
    const attachmentId = typeof input.attachmentId === 'string' && input.attachmentId.trim().length
      ? input.attachmentId.trim()
      : '';

    const imageUrl =
      (typeof input.imageUrl === 'string' && input.imageUrl.trim().length ? input.imageUrl.trim() : '') ||
      (typeof input.src === 'string' && input.src.trim().length ? input.src.trim() : '') ||
      (typeof input.url === 'string' && input.url.trim().length ? input.url.trim() : '');

    let image = (input.image && typeof input.image === 'object' && !Array.isArray(input.image))
      ? { ...input.image }
      : {};

    // Reject any attempt to pass base64 attachments via image payload
    if (typeof image.attachment === 'string' && String(image.attachment).trim().length) {
      throw new Error('image.attachment is not allowed. Use imageUrl or attachmentId.');
    }

    // Merge "metadata" (arbitrary Shopify image fields like alt, position, variant_ids, etc.)
    if (metadata) image = { ...metadata, ...image };

    // Convenience shortcuts
    if (typeof input.alt === 'string' && input.alt.trim().length && image.alt === undefined) image.alt = input.alt.trim();

    if (input.position !== undefined && image.position === undefined) {
      const n = Number(input.position);
      if (!Number.isFinite(n)) throw new Error('position must be a number');
      image.position = n;
    }

    if (Array.isArray(input.variantIds) && image.variant_ids === undefined) image.variant_ids = input.variantIds;

    if (operation === 'upload') {
      // Policy: upload must be via imageUrl or attachmentId only
      const hasSrc = !!(imageUrl || (typeof image.src === 'string' && image.src.trim().length));
      const hasAttachmentId = !!attachmentId;

      if (hasSrc && hasAttachmentId) {
        throw new Error('Provide exactly one of imageUrl (or image.src) OR attachmentId (not both).');
      }
      if (!hasSrc && !hasAttachmentId) {
        throw new Error('upload requires imageUrl (or image.src) OR attachmentId.');
      }

      if (hasSrc) {
        image.src = image.src ?? imageUrl;
        out.route = 'upload_url';
      } else {
        out.attachment_id = attachmentId;
        out.route = 'upload_attachment';
      }
    }

    if (operation === 'update') {
      if (attachmentId) throw new Error('attachmentId is not supported for update. Use imageUrl to change src, or metadata/image fields to update.');

      // Optional: allow updating src via imageUrl
      if (imageUrl) image.src = image.src ?? imageUrl;

      // Shopify REST update expects image.id in the body
      image.id = image.id ?? out.image_id;

      // Ensure there is at least one field to update besides id
      const keys = Object.keys(image).filter((k) => k !== 'id' && image[k] !== undefined);
      if (keys.length === 0) {
        throw new Error('update requires at least one field to update. Provide metadata and/or image (e.g., alt, position, variant_ids).');
      }

      out.route = 'update';
    }

    out.image = image;
  }

  if (!out.route) out.route = operation;
  return out;
}

async function main(ctx) {
  const prep = ctx.lastOutputOf('prep') || {};
  const resp = ctx.lastOutputOf('resolve_attachment') || {};
  const status = Number(resp.status);

  if (!Number.isFinite(status) || status < 200 || status >= 300) {
    const snippet = (() => {
      try { return JSON.stringify(resp.body); } catch { return String(resp.body ?? ''); }
    })();
    throw new Error(`Failed to resolve attachment preview URL (status ${resp.status}). body: ${snippet.slice(0, 500)}`);
  }

  const body = resp.body;

  // Heuristic extraction across possible response envelopes
  const candidates = [];
  function pushIfUrl(v) {
    if (typeof v === 'string' && /^https?:\/\//.test(v)) candidates.push(v);
  }

  if (body && typeof body === 'object') {
    const data = body.data ?? body;
    if (data && typeof data === 'object') {
      // common shapes
      if (Array.isArray(data.attachments)) {
        for (const a of data.attachments) {
          if (a && typeof a === 'object') {
            pushIfUrl(a.previewUrl);
            pushIfUrl(a.preview_url);
            pushIfUrl(a.url);
          }
        }
      }
      if (Array.isArray(data.items)) {
        for (const a of data.items) {
          if (a && typeof a === 'object') {
            pushIfUrl(a.previewUrl);
            pushIfUrl(a.preview_url);
            pushIfUrl(a.url);
          }
        }
      }
      // sometimes direct mapping: { [id]: { previewUrl } }
      for (const k of Object.keys(data)) {
        const v = data[k];
        if (v && typeof v === 'object') {
          pushIfUrl(v.previewUrl);
          pushIfUrl(v.preview_url);
          pushIfUrl(v.url);
        }
      }
      pushIfUrl(data.previewUrl);
      pushIfUrl(data.preview_url);
    }
  }

  const previewUrl = candidates[0] || null;
  if (!previewUrl) throw new Error('Attachment preview URL not found in Starships response.');

  const image = (prep.image && typeof prep.image === 'object') ? { ...prep.image } : {};
  if (typeof image.attachment === 'string' && image.attachment.trim().length) {
    throw new Error('image.attachment is not allowed. Use attachmentId to resolve to a URL.');
  }

  image.src = image.src ?? previewUrl;

  return {
    operation: 'upload',
    route: 'upload_attachment',
    product_id: String(prep.product_id),
    image,
  };
}

async function main(ctx) {
  const prep = ctx.lastOutputOf('prep') || {};
  const op = prep.operation;
  const resp = ctx.input || {};

  const status = Number(resp.status);
  const ok = Number.isFinite(status) ? (status >= 200 && status < 300) : false;

  return {
    ok,
    operation: op,
    status: resp.status,
    statusText: resp.statusText,
    url: resp.url,
    data: resp.body,
  };
}
